        bool aFaceBoundOrientation1 = GetFaceBoundOrientation(anOrientedEdge1, theShareTool);
        bool anIsCumulated1 = aFaceBoundOrientation1 != anOrientedEdge1.Orientation();

        aSharedEntitiesIt.Next();

        StepShape_OrientedEdge anOrientedEdge2 = aSharedEntitiesIt.Value() as StepShape_OrientedEdge;
        bool aFaceBoundOrientation2 = GetFaceBoundOrientation(anOrientedEdge2, theShareTool);
        bool anIsCumulated2 = aFaceBoundOrientation2 != anOrientedEdge2.Orientation();

        // the orientation of the OrientedEdges must be opposite
        if (anIsCumulated1 == anIsCumulated2)
        {
            theMessageTool.AddFail("ERROR: non 2-manifold topology");
        }
    }

