    private static bool AreEndsMatch(StepShape_EdgeCurve theEdgeCurve)
    {
        StepShape_VertexPoint aStartVertex = theEdgeCurve.EdgeStart() as StepShape_VertexPoint;
        StepShape_VertexPoint anEndVertex = theEdgeCurve.EdgeEnd() as StepShape_VertexPoint;
        if (aStartVertex == anEndVertex)
        {
            return false;
        }

        StepGeom_CartesianPoint aStartPoint = aStartVertex.VertexGeometry() as StepGeom_CartesianPoint;
        StepGeom_CartesianPoint anEndPoint = anEndVertex.VertexGeometry() as StepGeom_CartesianPoint;
        if ((aStartPoint is null) || (anEndPoint is null))
        {
            return false;
        }

        double aDistance = Math.Sqrt((aStartPoint.CoordinatesValue(1) - anEndPoint.CoordinatesValue(1)) * (aStartPoint.CoordinatesValue(1) - anEndPoint.CoordinatesValue(1)) + (aStartPoint.CoordinatesValue(2) - anEndPoint.CoordinatesValue(2)) * (aStartPoint.CoordinatesValue(2) - anEndPoint.CoordinatesValue(2)) + (aStartPoint.CoordinatesValue(3) - anEndPoint.CoordinatesValue(3)) * (aStartPoint.CoordinatesValue(3) - anEndPoint.CoordinatesValue(3)));
